import React, { useState, useEffect } from 'react';
import { getExamData } from '../services/api';

const ExamDataUser = () => {
  const [examDataList, setExamDataList] = useState([]);
  const [filteredExamData, setFilteredExamData] = useState([]);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedFranchise, setSelectedFranchise] = useState('');  // For franchise selection

  useEffect(() => {
    const fetchExamData = async () => {
      try {
        const response = await getExamData();
        if (response && response.length > 0) {
          const allExamData = response.flatMap(franchise =>
            (franchise.examData || []).map(exam => ({
              franchiseId: franchise._id,  // Store franchise id for filtering
              franchiseName: franchise.name,
              location: franchise.location,
              name: exam.takerName,         // Correct field for exam taker's name
              examName: exam.examName,      // Name of the exam
              date: new Date(exam.date).toLocaleDateString(),  // Formatted date
              duration: exam.durationInMinutes, // Duration in minutes
              status: exam.status           // Exam status (completed, etc.)
            }))
          );
          setExamDataList(allExamData);
          setFilteredExamData(allExamData); // Initially display all exam data
        } else {
          setErrorMessage('No exam data available for your franchises.');
        }
      } catch (error) {
        console.error('Error fetching exam data:', error);
        setErrorMessage('Unable to retrieve exam data. Please try again later.');
      }
    };

    fetchExamData();
  }, []);

  // Handle franchise filter change
  const handleFranchiseChange = (e) => {
    const franchiseName = e.target.value;
    setSelectedFranchise(franchiseName);

    if (franchiseName === '') {
      setFilteredExamData(examDataList);  // Show all data if no franchise is selected
    } else {
      const filteredData = examDataList.filter(exam => exam.franchiseName === franchiseName);
      setFilteredExamData(filteredData);
    }
  };

  // Handle change in input fields for editable data
  const handleInputChange = (index, field, value) => {
    const updatedData = [...filteredExamData];
    updatedData[index][field] = value;
    setFilteredExamData(updatedData);
  };

  // Save updated exam data (this can be used to make API calls if necessary)
  const handleSave = (index) => {
    const updatedExam = filteredExamData[index];
    console.log('Updated Exam:', updatedExam);
    // Here you can call an API to save the updated data
  };

  // Get distinct franchise names for the dropdown filter
  const franchiseNames = [...new Set(examDataList.map(exam => exam.franchiseName))];

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Exam Data</h1>

      {errorMessage ? (
        <p style={styles.error}>{errorMessage}</p>
      ) : (
        <>
          {/* Franchise filter dropdown */}
          <div style={styles.filterContainer}>
            <label style={styles.filterLabel}>Select Franchise:</label>
            <select
              value={selectedFranchise}
              onChange={handleFranchiseChange}
              style={styles.filterSelect}
            >
              <option value="">All Franchises</option>
              {franchiseNames.map((franchise, index) => (
                <option key={index} value={franchise}>
                  {franchise}
                </option>
              ))}
            </select>
          </div>

          {filteredExamData.length > 0 ? (
            <div style={styles.tableContainer}>
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>Franchise Name</th>
                    <th style={styles.th}>Location</th>
                    <th style={styles.th}>Exam Taker Name</th>
                    <th style={styles.th}>Exam Name</th>
                    <th style={styles.th}>Date</th>
                    <th style={styles.th}>Duration (minutes)</th>
                    <th style={styles.th}>Status</th>
                    <th style={styles.th}>Actions</th> {/* Save Button */}
                  </tr>
                </thead>
                <tbody>
                  {filteredExamData.map((exam, index) => (
                    <tr key={index} style={styles.tr}>
                      <td style={styles.td}>
                        <input
                          type="text"
                          value={exam.franchiseName}
                          onChange={(e) => handleInputChange(index, 'franchiseName', e.target.value)}
                          style={styles.input}
                        />
                      </td>
                      <td style={styles.td}>
                        <input
                          type="text"
                          value={exam.location}
                          onChange={(e) => handleInputChange(index, 'location', e.target.value)}
                          style={styles.input}
                        />
                      </td>
                      <td style={styles.td}>
                        <input
                          type="text"
                          value={exam.name}
                          onChange={(e) => handleInputChange(index, 'name', e.target.value)}
                          style={styles.input}
                        />
                      </td>
                      <td style={styles.td}>
                        <input
                          type="text"
                          value={exam.examName}
                          onChange={(e) => handleInputChange(index, 'examName', e.target.value)}
                          style={styles.input}
                        />
                      </td>
                      <td style={styles.td}>
                        <input
                          type="date"
                          value={new Date(exam.date).toISOString().split('T')[0]} // Convert date format for input
                          onChange={(e) => handleInputChange(index, 'date', e.target.value)}
                          style={styles.input}
                        />
                      </td>
                      <td style={styles.td}>
                        <input
                          type="number"
                          value={exam.duration}
                          onChange={(e) => handleInputChange(index, 'duration', e.target.value)}
                          style={styles.input}
                        />
                      </td>
                      <td style={styles.td}>
                        <input
                          type="text"
                          value={exam.status}
                          onChange={(e) => handleInputChange(index, 'status', e.target.value)}
                          style={styles.input}
                        />
                      </td>
                      <td style={styles.td}>
                        <button
                          onClick={() => handleSave(index)}
                          style={styles.saveButton}
                        >
                          Save
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p style={styles.noData}>No exam data available for the selected franchise.</p>
          )}
        </>
      )}
    </div>
  );
};

// CSS styles in JS format
const styles = {
  container: {
    padding: '20px',
    backgroundColor: '#f8f9fa',
    minHeight: '100vh',
  },
  header: {
    fontSize: '2rem',
    textAlign: 'center',
    marginBottom: '20px',
  },
  tableContainer: {
    overflowX: 'auto',
    marginTop: '20px',
  },
  table: {
    width: '100%',
    borderCollapse: 'collapse',
    tableLayout: 'fixed',
    marginBottom: '20px',
  },
  th: {
    padding: '12px',
    backgroundColor: '#007bff',
    color: 'white',
    textAlign: 'left',
    border: '1px solid #ddd',
  },
  td: {
    padding: '12px',
    textAlign: 'left',
    border: '1px solid #ddd',
  },
  tr: {
    transition: 'background-color 0.3s ease',
  },
  error: {
    color: 'red',
    textAlign: 'center',
    marginBottom: '20px',
  },
  noData: {
    textAlign: 'center',
    padding: '20px',
    color: '#888',
  },
  filterContainer: {
    marginBottom: '20px',
    textAlign: 'center',
  },
  filterLabel: {
    marginRight: '10px',
    fontSize: '1rem',
  },
  filterSelect: {
    padding: '8px',
    fontSize: '1rem',
    borderRadius: '4px',
    border: '1px solid #ddd',
  },
  input: {
    padding: '8px',
    fontSize: '1rem',
    borderRadius: '4px',
    border: '1px solid #ddd',
    width: '100%',
  },
  saveButton: {
    backgroundColor: '#28a745',
    color: 'white',
    padding: '6px 12px',
    borderRadius: '4px',
    border: 'none',
    cursor: 'pointer',
  },
};

export default ExamDataUser;
